<?php require_once __DIR__.'/professional_assets/bootstrap_portal.php'; require_role(['admin','worker','doctor']);
$con->query("CREATE TABLE IF NOT EXISTS admissions (id INT AUTO_INCREMENT PRIMARY KEY, patient_id INT NOT NULL, doctor_id INT DEFAULT 0, ward VARCHAR(100) DEFAULT '', room VARCHAR(50) DEFAULT '', bed VARCHAR(50) DEFAULT '', admission_date DATE NOT NULL, discharge_date DATE NULL, status VARCHAR(30) DEFAULT 'Admitted', notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(patient_id),INDEX(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $s=$con->prepare("INSERT INTO admissions(patient_id,doctor_id,ward,room,bed,admission_date,status,notes) VALUES(?,?,?,?,?,?,?,?)");$p=(int)($_POST['patient_id']??0);$d=(int)($_POST['doctor_id']??0);$w=trim($_POST['ward']??'');$r=trim($_POST['room']??'');$b=trim($_POST['bed']??'');$dt=$_POST['admission_date']??date('Y-m-d');$st=$_POST['status']??'Admitted';$n=trim($_POST['notes']??'');$s->bind_param('iissssss',$p,$d,$w,$r,$b,$dt,$st,$n);if($s->execute())$msg='Admission recorded.';}
$patients=$con->query("SELECT patientid,patientname FROM patient ORDER BY patientname");$doctors=$con->query("SELECT doctorid,doctorname FROM doctor WHERE status='Active' ORDER BY doctorname");$rows=$con->query("SELECT a.*,p.patientname,COALESCE(d.doctorname,'') doctorname FROM admissions a JOIN patient p ON p.patientid=a.patient_id LEFT JOIN doctor d ON d.doctorid=a.doctor_id ORDER BY a.id DESC LIMIT 100");
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="professional_assets/app.css"><link rel="stylesheet" href="professional_assets/theme.css.php"><title>Admissions</title></head><body class="module-body"><div class="module-wrap"><div class="module-head"><div><span class="eyebrow">INPATIENT</span><h1>Admissions & Beds</h1><p>Admit patients, assign ward/room/bed, discharge and transfer.</p></div></div><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><div class="panel"><h2>New admission</h2><form method="post" class="form-grid"><label>Patient<select name="patient_id" required><?php while($p=$patients->fetch_assoc()):?><option value="<?=$p['patientid']?>"><?=esc($p['patientname'])?></option><?php endwhile;?></select></label><label>Doctor<select name="doctor_id"><option value="0">Not assigned</option><?php while($d=$doctors->fetch_assoc()):?><option value="<?=$d['doctorid']?>"><?=esc($d['doctorname'])?></option><?php endwhile;?></select></label><label>Ward<input name="ward"></label><label>Room<input name="room"></label><label>Bed<input name="bed"></label><label>Admission date<input type="date" name="admission_date" value="<?=date('Y-m-d')?>"></label><label>Status<select name="status"><option>Admitted</option><option>Transferred</option><option>Discharged</option></select></label><label>Notes<textarea name="notes"></textarea></label><button class="primary-btn">Save admission</button></form></div><div class="panel"><h2>Admission history</h2><div class="table-wrap"><table><thead><tr><th>Patient</th><th>Doctor</th><th>Ward</th><th>Room</th><th>Bed</th><th>Admitted</th><th>Status</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=esc($r['patientname'])?></td><td><?=esc($r['doctorname'])?></td><td><?=esc($r['ward'])?></td><td><?=esc($r['room'])?></td><td><?=esc($r['bed'])?></td><td><?=esc($r['admission_date'])?></td><td><?=esc($r['status'])?></td></tr><?php endwhile;?></tbody></table></div></div></div></body></html>
